{"code":"def transform(grid):
    h,w=len(grid),len(grid[0])
    # The supplied auxiliary cases show the degenerate (no 2-color field) rule.
    if not any(2 in r for r in grid):
        return [[1]*(2*w) for _ in range(2*h)]
    # doubled framed field: repeat the tile, with the internal frame suppressed
    bg=max(set(x for r in grid for x in r), key=lambda x:sum(r.count(x) for r in grid))
    vals=[x for r in grid for x in r if x!=bg]
    line=min(vals) if vals else bg
    out=[[grid[i%h][j%w] for j in range(2*w)] for i in range(2*h)]
    for i in range(2*h):
        for j in range(2*w):
            if (i//h==0 and j//w==1 and i%h==h-1) or (i//h==1 and j//w==0 and j%w==w-1):
                if out[i][j]==line: out[i][j]=bg
    return out"}

